const menu=document.getElementById('menu'),toggle=document.getElementById('menu-toggle');
function closeMenu(){menu.hidden=true;toggle.setAttribute('aria-expanded','false');document.body.classList.remove('menu-open')}
toggle.addEventListener('click',()=>{const open=toggle.getAttribute('aria-expanded')!=='true';menu.hidden=!open;toggle.setAttribute('aria-expanded',String(open));document.body.classList.toggle('menu-open',open);if(open)menu.querySelector('a').focus()});
menu.querySelectorAll('a').forEach(a=>a.addEventListener('click',closeMenu));document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeMenu();toggle.focus()}});
const cfg=window.JONAAS_CONTENT;
document.querySelectorAll('[data-link]').forEach(a=>a.href=cfg.links[a.dataset.link]);
const list=document.getElementById('track-list');cfg.tracks.slice(2).forEach((t,i)=>{const a=document.createElement('a');a.className='track';a.href=t.url||'https://open.spotify.com/search/'+encodeURIComponent('Jonaas '+t.title);a.target='_blank';a.rel='noopener';a.setAttribute('aria-label',t.title+(t.url?' — ouvir no Spotify':' — procurar no Spotify'));const values=[String(i+1).padStart(2,'0'),t.title,t.project,t.duration,'↗'];['number','title','project','duration','arrow'].forEach((key,j)=>{const span=document.createElement('span');span.className='track-'+key;span.textContent=values[j];a.append(span)});list.append(a)});
const video=document.getElementById('video-dialog');const videoFrame=document.getElementById('video-frame');document.getElementById('watch-video').addEventListener('click',()=>{videoFrame.innerHTML='<iframe src="https://www.youtube-nocookie.com/embed/-kclssxMYOQ?autoplay=1&rel=0" title="Jonaas — Clipe oficial" allow="autoplay; encrypted-media; picture-in-picture; fullscreen" allowfullscreen></iframe>';video.showModal()});document.getElementById('close-video').addEventListener('click',()=>video.close());video.addEventListener('close',()=>{videoFrame.replaceChildren()});video.addEventListener('click',e=>{if(e.target===video){const r=video.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)video.close()}});
const listen=document.getElementById('listen-inline'),player=document.getElementById('spotify-player');listen.setAttribute('aria-expanded','false');listen.setAttribute('aria-controls','spotify-player');listen.addEventListener('click',()=>{player.hidden=!player.hidden;listen.setAttribute('aria-expanded',String(!player.hidden));listen.innerHTML=player.hidden?'OUVIR AQUI <span>＋</span>':'FECHAR LEITOR <span>−</span>';if(player.hidden)player.replaceChildren();else player.innerHTML='<iframe title="Ouvir Vou Fazer Mais Como no Spotify" src="https://open.spotify.com/embed/track/49gOZ8KgMgbIA402epjfaz?utm_source=generator&theme=0" allow="autoplay; clipboard-write; encrypted-media; fullscreen; picture-in-picture" loading="lazy"></iframe>'});
const motion=matchMedia('(prefers-reduced-motion: reduce)'),story=document.querySelector('.scroll-story'),photo=document.querySelector('.hero-photo'),word=document.querySelector('.hero-word'),copy=document.querySelector('.hero-copy'),origin=document.querySelector('.origin-overlay');let queued=false;const clamp=(x)=>Math.max(0,Math.min(1,x));
function renderScroll(){queued=false;if(motion.matches){[photo,word,copy,origin].forEach(e=>e.removeAttribute('style'));copy.inert=false;return}const rect=story.getBoundingClientRect();const p=clamp(-rect.top/(story.offsetHeight-innerHeight));const opening=clamp((p-.08)/.35);const arrival=clamp((p-.38)/.2);const departure=clamp((p-.85)/.15);photo.style.transform=`scale(${1.02+p*.18}) translateY(${p*-3}%)`;photo.style.filter=`brightness(${.84-p*.4})`;word.style.transform=`translateY(${-opening*80}px) scale(${1+opening*.13})`;word.style.opacity=String(.85*(1-opening));copy.style.opacity=String(1-opening);copy.style.transform=`translateY(${opening*-25}px)`;copy.style.visibility=opening>.99?'hidden':'visible';copy.inert=opening>.99;origin.style.opacity=String(arrival*(1-departure));origin.style.transform=`translateY(${(1-arrival)*30}px)`;}
function schedule(){if(!queued){queued=true;requestAnimationFrame(renderScroll)}}addEventListener('scroll',schedule,{passive:true});addEventListener('resize',schedule);motion.addEventListener('change',schedule);schedule();
menu.addEventListener('keydown',e=>{if(e.key!=='Tab')return;const anchors=[...menu.querySelectorAll('a')];if(e.shiftKey&&document.activeElement===anchors[0]){e.preventDefault();toggle.focus()}else if(!e.shiftKey&&document.activeElement===anchors.at(-1)){e.preventDefault();toggle.focus()}});toggle.addEventListener('keydown',e=>{if(!menu.hidden&&e.key==='Tab'){e.preventDefault();const links=menu.querySelectorAll('a');(e.shiftKey?links[links.length-1]:links[0]).focus()}});
